svg.ic.lg { width: 28px; height: 28px; } svg.ic.xl { width: 44px; height: 44px; stroke-width: 1.6; } svg.ic.sm { width: 16px; height: 16px; }

/* panels */
.panel { background: linear-gradient(180deg, var(--panel), var(--bg-2)); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); min-width: 0; }
.panel > .panel-head { display: flex; align-items: center; gap: 10px; padding: 14px 16px 10px; }
