.btn:hover { border-color: #3b5685; } .btn:active { transform: scale(.98); }
.btn:focus-visible, .field:focus-visible, .seg button:focus-visible, .tile:focus-visible { outline: 2px solid var(--teal); outline-offset: 2px; }
.btn.primary { background: linear-gradient(180deg, #21e0d1, var(--teal-2)); color: var(--teal-ink); border-color: transparent; font-weight: 700; box-shadow: 0 6px 20px rgba(25, 211, 197, .25); }
