.seg button.on, .seg button[aria-selected="true"] { background: var(--teal-soft); border-color: var(--teal-line); color: var(--teal); }

/* chips / status */
.chip { display: inline-flex; align-items: center; gap: 6px; padding: 3px 10px; border-radius: 999px; font-size: 12.5px; font-weight: 600; border: 1px solid var(--line-2); background: var(--panel-2); color: var(--ink-2); white-space: nowrap; }
