.chip.ok { color: var(--ok); border-color: rgba(52, 211, 153, .4); background: var(--ok-soft); } .chip.ok .dot, .dot.ok { background: var(--ok); }
.chip.warn { color: var(--warn); border-color: var(--warn-line); background: var(--warn-soft); } .chip.warn .dot, .dot.warn { background: var(--warn); }
