.form { display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 12px 14px; align-items: start; }
.check { display: inline-flex; align-items: center; gap: 9px; min-height: 36px; cursor: pointer; color: var(--ink-2); }
.check input { width: 20px; height: 20px; accent-color: var(--teal); margin: 0; flex: none; }

/* toggle */
.toggle { position: relative; width: 50px; height: 28px; border-radius: 999px; border: 1px solid var(--line-2); background: var(--panel-3); cursor: pointer; flex: none; padding: 0; }
.toggle::after { content: ""; position: absolute; top: 3px; left: 3px; width: 20px; height: 20px; border-radius: 50%; background: #c9d6ea; transition: transform .14s; }
.toggle.on, .toggle[aria-checked="true"] { background: var(--teal); border-color: transparent; }
.toggle.on::after, .toggle[aria-checked="true"]::after { transform: translateX(22px); background: #fff; }

/* slider */
input[type=range].slider { -webkit-appearance: none; appearance: none; width: 100%; height: 36px; background: transparent; margin: 0; cursor: pointer; }
input[type=range].slider::-webkit-slider-runnable-track { height: 8px; border-radius: 99px; background: linear-gradient(90deg, var(--teal) var(--fill, 50%), var(--panel-3) var(--fill, 50%)); }
