input[type=range].slider::-moz-range-progress { height: 8px; border-radius: 99px; background: var(--teal); }
input[type=range].slider::-webkit-slider-thumb { -webkit-appearance: none; width: 24px; height: 24px; border-radius: 50%; background: #e9fbf9; border: 3px solid var(--teal); margin-top: -8px; box-shadow: 0 2px 8px rgba(0, 0, 0, .4); }
input[type=range].slider::-moz-range-thumb { width: 18px; height: 18px; border-radius: 50%; background: #e9fbf9; border: 3px solid var(--teal); }
input[type=range].slider:disabled { opacity: .45; }

/* tables */
table.tbl { width: 100%; border-collapse: collapse; font-size: 14px; }
table.tbl th { text-align: left; font-size: 12px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); font-weight: 650; padding: 8px 10px; border-bottom: 1px solid var(--line); white-space: nowrap; }
table.tbl td { padding: 9px 10px; border-bottom: 1px solid var(--line); vertical-align: middle; }
