      var x0 = W, y0 = H, x1 = 0, y1 = 0;
      function grow(ax, ay, bx, by) { x0 = Math.min(x0, ax); y0 = Math.min(y0, ay); x1 = Math.max(x1, bx); y1 = Math.max(y1, by); }
