        g.appendChild(O.svg('text', { x: b.x + w / 2, y: b.y + hh / 2, 'font-size': fs, 'text-anchor': 'middle', 'dominant-baseline': 'central' }, fit(scene.name, w - 12, fs)));
        svg.appendChild(g);
