      var cx = L.x + w / 2, cy = L.y + hh / 2;
      var turned = Math.abs(rot % 180) === 90;
      var tw = turned ? hh : w, th = turned ? w : hh;
      var g = O.svg('g', { role: opts.onDisplay ? 'button' : null, 'aria-label': d.name, onclick: opts.onDisplay ? function () { opts.onDisplay(d); } : null });
      var body = O.svg('g', rot ? { transform: 'rotate(' + rot + ' ' + cx + ' ' + cy + ')' } : null);
      body.appendChild(O.svg('rect', { 'class': 'ring', x: L.x - 5, y: L.y - 5, width: w + 10, height: hh + 10, rx: 9 }));
      body.appendChild(O.svg('rect', { 'class': 'body', x: L.x, y: L.y, width: w, height: hh, rx: 6 }));
      g.appendChild(body);
      var src = null;
      if (!opts.compact) {
        /* The name on one line when it fits at a readable size, else on two; then the
           source line. Shrink before cutting short. */
        var name = String(d.name || ''), lines = [name];
        var fs = VF.clamp(th * 0.3, 9, 15);
        var need = name.length * 0.56;
        if ((tw - 6) / need < 11 && th >= 40 && name.indexOf(' ') > 0) {
          var mid = name.length / 2, cut = -1;
          for (var i = 0; i < name.length; i++) if (name.charAt(i) === ' ' && (cut < 0 || Math.abs(i - mid) < Math.abs(cut - mid))) cut = i;
          lines = [name.slice(0, cut), name.slice(cut + 1)];
          need = Math.max(lines[0].length, lines[1].length) * 0.56;
          fs = VF.clamp(th * 0.25, 9, 13);
        }
        fs = Math.max(9, Math.min(fs, (tw - 6) / Math.max(1, need)));
        var fs2 = VF.clamp(th * 0.24, 8, 12);
        var ys = lines.length === 2 ? [cy - th * 0.29, cy - th * 0.03] : [cy - th * 0.17];
        lines.forEach(function (line, n) {
          g.appendChild(O.svg('text', { 'class': 'nm', x: cx, y: ys[n], 'font-size': fs, 'text-anchor': 'middle', 'dominant-baseline': 'central' }, fit(line, tw - 6, fs)));
        });
        src = O.svg('text', { 'class': 'src', x: cx, y: cy + th * (lines.length === 2 ? 0.3 : 0.24), 'font-size': fs2, 'text-anchor': 'middle', 'dominant-baseline': 'central' });
        src._w = tw - 6; src._fs = fs2;
        g.appendChild(src);
      }
      svg.appendChild(g);
      items.push({ g: g, d: d, src: src, cls: '' });
    });

    function update() {
      items.forEach(function (it) {
        var info = O.displayInfo(it.d);
        var cls = 'op-pd ' + info.key + (opts.selection !== false && O.selection.has(it.d.id) ? ' sel' : '') + (opts.onDisplay ? ' tap' : '');
        if (it.cls !== cls) { it.cls = cls; it.g.setAttribute('class', cls); }
        if (it.src) O.setText(it.src, fit(info.line, it.src._w, it.src._fs));
      });
      zoneItems.forEach(function (it) {
        var c = VF.asMap(VF.asMap(O.doc().zones)[it.z.id]);
        var power = c.power || {}, vol = c.volume || {}, mu = c.mute || {};
        var working = ['power', 'source', 'volume', 'mute'].some(function (f) { return (c[f] || {}).status === 'pending'; });
        var failed = ['power', 'source', 'volume', 'mute'].some(function (f) { return (c[f] || {}).status === 'failed'; });
        var text = mu.value === true ? 'Muted' : (power.value === 'off' ? 'Off' : (typeof vol.value === 'number' ? vol.value + '%' : 'Unknown'));
        O.setText(it.val, text);
        var cls = 'op-pzone' + (mu.value === true ? ' muted' : '') + (power.value === 'on' ? ' on' : '') + (working ? ' working' : '') + (failed ? ' failed' : '');
        if (it.cls !== cls) { it.cls = cls; it.g.setAttribute('class', cls); }
      });
      sceneItems.forEach(function (it) {
        var st = O.sceneState(it.scene);
        var cls = 'op-pscene' + (st.active ? ' on' : '') + (st.running ? ' busy' : '');
        if (it.cls !== cls) { it.cls = cls; it.g.setAttribute('class', cls); }
      });
    }
    update();
    return { el: svg, update: update, count: items.length };
  };

  /* ── full-screen notices and sign-in ─────────────────────────────────── */
  function brand() { return h('div.op-brand', h('span.op-logo', VF.icon('activity')), h('span', 'Venue', h('b', 'Flow'))); }
  function studioUrl() { return (VF.transport.relay || '') + '/studio'; }
  function leaveShell() {
    VF.poll.stop();
    if (current && current.view && current.view.destroy) { try { current.view.destroy(); } catch (e) { console.error(e); } }
    current = null; ui = null; closeMenu();
  }
  function notice(icon, title, text, extra) {
    leaveShell();
    VF.mount(root, h('div.op-notice', h('div.op-notice-box', brand(), VF.icon(icon, 'xl'), h('h1', title), text ? h('p.muted', text) : null, extra)));
  }
  var retryTimer = null;
  function showUnreachable(reply) {
    notice('alert', 'Cannot reach the controller', (reply && reply.errorCode !== 'VF_NETWORK' && reply.message) || 'Check that this screen is on the venue network. Trying again every few seconds.',
      h('button.btn.primary', { type: 'button', onclick: function () { hello(); } }, VF.icon('refresh'), 'Try again'));
    clearTimeout(retryTimer);
    retryTimer = setTimeout(function () { if (!ui) hello(); }, 4000);
  }

  function showSignIn(cancel) {
    leaveShell();
    var d = O.hello || {};
    var profiles = VF.asList(d.profiles);
    var msg = h('div.op-signin-msg', { role: 'alert' });
    var buttons = [];
    var lockedUntil = 0, lockTimer = null;
    function setMsg(kind, text) { VF.mount(msg, text ? h('div.banner.' + kind, VF.icon('alert'), h('div', text)) : null); }
    function tick() {
      var left = Math.ceil((lockedUntil - Date.now()) / 1000);
      if (left <= 0) {
        clearInterval(lockTimer); lockTimer = null;
        buttons.forEach(function (b) { b.disabled = false; });
        setMsg('', '');
        return;
      }
      buttons.forEach(function (b) { b.disabled = true; });
      setMsg('warn', 'Too many wrong attempts. Try again in ' + left + ' s.');
    }
    function lock(seconds) { lockedUntil = Date.now() + seconds * 1000; clearInterval(lockTimer); lockTimer = setInterval(tick, 1000); tick(); }
    function pick(p) {
      setMsg('', '');
      VF.pinPad('Enter PIN', p.name).then(function (pin) {
        if (!pin) return;
        var old = VF.session.get();
        VF.api('PROFILE_LOGIN', { profileId: p.id, pin: pin }, { since: false }).then(function (r) {
          if (r.ok && r.data && r.data.session && r.data.profile) {
            clearInterval(lockTimer);
            if (old) VF.api('LOGOUT', {}, { since: false });      // ends the session this one replaces
            VF.session.set(r.data.session);
            var data = Object.assign({}, d, r.data, { signedIn: true, needsSignIn: false });
            enter(data);
            VF.toast('Signed in as ' + r.data.profile.name, 'ok');
            return;
          }
          var retry = Number(r.data && r.data.retryIn) || 0;
          if (r.errorCode === 'VF_LOCKED') lock(retry > 0 ? retry : 60);
          else setMsg(r.errorCode === 'VF_BAD_PIN' ? 'warn' : 'bad', r.message || 'That did not work.');
        });
      });
    }
    profiles.forEach(function (p) {
      buttons.push(h('button.btn.lg.op-signin-btn', { type: 'button', onclick: function () { pick(p); } },
        VF.icon('user', 'lg'), h('div.grow', h('div.op-signin-name', p.name), h('div.small.muted', ROLE[p.role] || 'Staff')), VF.icon('chevron-right')));
    });
    var body;
    if (O.asStudio) {
      body = h('div.col', h('p.muted', 'Sign in to the Installer Studio in this tab first, then open this page again.'), h('a.btn.primary', { href: studioUrl() }, VF.icon('settings'), 'Open Installer Studio'));
    } else if (!profiles.length) {
      body = h('div.col', h('p.muted', 'No staff profile can sign in on this screen yet. Ask your installer to set a PIN for a profile.'),
        d.studioEnabled ? h('a.btn', { href: studioUrl() }, VF.icon('settings'), 'Installer Studio') : null);
    } else {
      body = h('div.col', h('p.muted', 'Choose your profile, then enter your PIN.'), msg, h('div.op-signin-list', buttons));
    }
    VF.mount(root, h('div.op-notice.scroll', h('div.op-notice-box.op-signin', brand(), d.venueName ? h('div.op-signin-venue', d.venueName) : null,
      h('h1', cancel ? 'Switch profile' : 'Sign in'), body,
      cancel ? h('button.btn.ghost', { type: 'button', onclick: function () { clearInterval(lockTimer); cancel(); } }, VF.icon('arrow-left'), 'Back') : null)));
  }

  /* ── the shell ───────────────────────────────────────────────────────── */
  function setData(d) {
    var c = VF.asMap(d.config);
    O.config = c;
    O.lists = {}; O.ix = {};
    ['floors', 'areas', 'sources', 'displays', 'audioZones', 'groups', 'lighting', 'shades', 'rooms', 'scenes', 'labels', 'sceneButtons'].forEach(function (k) {
      var list = VF.asList(c[k]).filter(function (x) { return x && typeof x === 'object'; });
      var map = {};
      list.forEach(function (x) { if (x.id) map[x.id] = x; });
      O.lists[k] = list; O.ix[k] = map;
    });
    var p = VF.asMap(d.profile);
    var venue = VF.asMap(c.venue);
    /* An Installer Studio session is "System": every interface, every permission. */
    var allowed = p.system ? ORDER : VF.asList(p.interfaces);
    O.profile = {
      id: p.id || (p.system ? 'system' : ''),
      name: p.system ? 'Installer' : (p.name || 'Staff'),
      role: p.role || '', system: p.system === true,
      interfaces: ORDER.filter(function (x) { return allowed.indexOf(x) >= 0 && factories[x]; }),
      defaultInterface: p.system ? venue.defaultInterface : p.defaultInterface,
      can: VF.asMap(p.can)
    };
    O.signedIn = d.signedIn === true;
    O.venueName = d.venueName || venue.name || 'Venue';
    O.selection.prune();
    if (!O.find('sources', O.pick.sourceId)) O.pick.sourceId = '';
    if (!O.find('audioZones', O.pick.zoneId)) O.pick.zoneId = '';
  }
  /* Compared between two HELLO replies, so it must not depend on the order in which the
     driver's JSON encoder happens to write the keys. */
  function stable(x) {
    if (Array.isArray(x)) return x.map(stable);
    if (x && typeof x === 'object') { var o = {}; Object.keys(x).sort().forEach(function (k) { o[k] = stable(x[k]); }); return o; }
    return x;
  }
  function dataKey(d) { return JSON.stringify(stable([d.profile || null, d.config || null, d.venueName || '', d.signedIn === true])); }

  var lastKey = '', lastProfileId = null, lastViewId = null;
  function enter(d) {
    leaveShell();
    O.hello = d;
    lastKey = dataKey(d);
    setData(d);
    buildShell();
    if (d.state) VF.state.set(d.state);
    var keep = lastProfileId === O.profile.id && O.profile.interfaces.indexOf(lastViewId) >= 0;
    lastProfileId = O.profile.id;
    var first = keep ? lastViewId : (O.profile.interfaces.indexOf(O.profile.defaultInterface) >= 0 ? O.profile.defaultInterface : O.profile.interfaces[0]);
    show(first);
    paint();
    fitHeader();
    VF.poll.start(1500);
  }

  function buildShell() {
    ui = {};
    ui.sim = h('div.simbar.hidden', 'Simulation: no real equipment is being controlled');
    ui.venueDot = h('span.dot'); ui.venueText = h('span');
    ui.venue = h(O.can('venueStatus') ? 'button.chip.op-venue-chip.tap' : 'span.chip.op-venue-chip', O.can('venueStatus') ? { type: 'button', title: 'Open or close the venue', onclick: function () {
      O.setVenueStatus(O.doc().venueStatus === 'open' ? 'closed' : 'open');
    } } : {}, ui.venueDot, ui.venueText);
    ui.connDot = h('span.dot.ok'); ui.connText = h('span.op-conn-text', 'Connected');
    ui.conn = h('span.op-conn', { role: 'status' }, ui.connDot, ui.connText);
    ui.clock = h('span.op-clock');
    var items = menuItems();
    ui.profile = h(items.length ? 'button.op-profile.tap' : 'span.op-profile', items.length ? { type: 'button', 'aria-haspopup': 'true', onclick: function (e) { e.stopPropagation(); toggleMenu(items); } } : {},
      VF.icon('user'), h('span.ellipsis', O.profile.name), items.length ? VF.icon('chevron-down', 'sm') : null);
    ui.nav = null;
    if (O.profile.interfaces.length > 1) {
      ui.tabs = {};
      ui.nav = h('nav.seg.op-nav', { role: 'tablist', 'aria-label': 'Interface' }, O.profile.interfaces.map(function (id) {
        var def = O.INTERFACES[id];
        var b = h('button', { type: 'button', role: 'tab', onclick: function () { show(id); } }, VF.icon(def.icon), h('span', def.label));
        ui.tabs[id] = b;
        return b;
      }));
    }
    ui.venueName = h('div.op-venue.ellipsis', O.venueName);
    ui.banners = h('div.op-banners');
    ui.activity = h('div.op-activity');
    ui.main = h('main.op-main');
    ui.head = h('header.op-head', brand(), ui.venueName, ui.nav || h('div.grow'), h('div.op-head-right', ui.venue, ui.conn, ui.clock, ui.profile));
    VF.mount(root, h('div.op-shell', ui.sim, ui.head, ui.banners, ui.activity, ui.main));
    paintOnline();
    paintClock();
    fitHeader();
  }
  /* The venue name gives way first: when it is squeezed to a stub, hide it. */
  function fitHeader() {
    if (!ui || !ui.venueName) return;
    ui.venueName.classList.remove('hidden');
    ui.head.classList.remove('tight', 'tighter');
    if (ui.venueName.scrollWidth > ui.venueName.clientWidth + 1 && ui.venueName.clientWidth < 96) ui.venueName.classList.add('hidden');
    /* Then the clock, then the tab icons, before a tab is pushed out of sight. */
    if (ui.nav && ui.nav.scrollWidth > ui.nav.clientWidth + 1) {
      ui.head.classList.add('tight');
      if (ui.nav.scrollWidth > ui.nav.clientWidth + 1) ui.head.classList.add('tighter');
    }
  }

  function show(id) {
    if (!ui) return;
    if (current && current.view && current.view.destroy) { try { current.view.destroy(); } catch (e) { console.error(e); } }
    current = null;
    VF.clear(ui.main);
    if (!id || !factories[id]) {
      VF.mount(ui.main, h('div.op-view', h('div.empty', 'This profile has no screen assigned. Ask your installer to give it an interface.')));
      return;
    }
    lastViewId = id;
    if (ui.tabs) Object.keys(ui.tabs).forEach(function (k) { O.setClass(ui.tabs[k], 'on', k === id); O.setAttr(ui.tabs[k], 'aria-selected', k === id ? 'true' : 'false'); });
    var host = h('div.op-view.op-view-' + id);
    ui.main.appendChild(host);
    var view = null;
    try { view = factories[id](host) || {}; } catch (e) { console.error('VenueFlow view ' + id, e); VF.mount(host, h('div.empty', 'This screen could not be drawn.')); view = {}; }
    current = { id: id, view: view };
    if (view.update) view.update();
  }
  O.show = show;
  O.currentId = function () { return current ? current.id : null; };

  /* profile menu */
  var menuEl = null;
  function closeMenu() { if (menuEl && menuEl.parentNode) menuEl.parentNode.removeChild(menuEl); menuEl = null; document.removeEventListener('click', closeMenu); }
  function menuItems() {
    var items = [];
    if (O.profile.system) {
      items.push({ icon: 'settings', label: 'Back to Installer Studio', run: function () { location.href = studioUrl(); } });
      return items;
    }
    if (VF.asList(O.hello && O.hello.profiles).length) {
      items.push({ icon: 'users', label: 'Switch profile', run: function () { var d = O.hello; showSignIn(function () { enter(d); }); } });
    }
    if (O.signedIn) {
      items.push({ icon: 'log-out', label: 'Sign out', run: function () {
        VF.api('LOGOUT', {}, { since: false }).then(function () { VF.session.clear(); lastProfileId = null; hello(); });
      } });
    }
    return items;
  }
  function toggleMenu(items) {
    if (menuEl) { closeMenu(); return; }
    menuEl = h('div.op-menu', { role: 'menu' },
      h('div.op-menu-who', h('div', O.profile.name), h('div.small.muted', O.profile.system ? 'Full access' : ((ROLE[O.profile.role] || 'Staff') + (O.signedIn ? '' : ' (this screen)')))),
      items.map(function (it) { return h('button.btn.ghost.block', { type: 'button', role: 'menuitem', onclick: function () { closeMenu(); it.run(); } }, VF.icon(it.icon), h('span.grow', it.label)); }));
    var r = ui.profile.getBoundingClientRect();
    menuEl.style.top = Math.round(r.bottom + 6) + 'px';
    menuEl.style.right = Math.max(8, Math.round(window.innerWidth - r.right)) + 'px';
    document.body.appendChild(menuEl);
    setTimeout(function () { document.addEventListener('click', closeMenu); }, 0);
  }

  /* header + banners + activity */
  var isOnline = true;
  function paintOnline() {
    if (!ui) return;
    ui.connDot.className = 'dot ' + (isOnline ? 'ok' : 'bad');
    O.setText(ui.connText, isOnline ? 'Connected' : 'No connection');
    O.setClass(ui.conn, 'off', !isOnline);
    paintBanners();
  }
  function paintClock() {
    if (!ui) return;
    O.setText(ui.clock, new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
  }
  function paintBanners() {
    if (!ui) return;
    var doc = O.doc();
    var restricted = !!(doc.license && doc.license.restricted);
    O.patch(ui.banners, (isOnline ? '' : 'off') + (restricted ? 'lic' : ''), function () {
      return [
        isOnline ? null : h('div.banner.bad', VF.icon('alert'), h('div', 'Cannot reach the controller. What you see may be out of date. Trying again.')),
        restricted ? h('div.banner.warn', VF.icon('alert'), h('div', h('b', 'SmartBuildOS licence needed. '), 'Scenes and schedules are paused. Manual control keeps working.')) : null
      ];
    });
  }

  /* What an operation has done so far, in the words an operator uses. Counted from the
     targets this profile can see. */
  O.opCounts = function (op) {
    var c = { confirmed: 0, sent: 0, working: 0, unconfirmed: 0, refused: 0, replaced: 0, total: 0 };
    VF.asList(op.targets).forEach(function (t) {
      c.total++;
      if (t.status === 'confirmed') c.confirmed++;
      else if (t.status === 'commanded') c.sent++;
      else if (t.status === 'pending') c.working++;
      else if (t.status === 'unknown' || (t.status === 'failed' && t.errorCode === 'VF_NOT_CONFIRMED')) c.unconfirmed++;
      else if (t.status === 'superseded') c.replaced++;
      else c.refused++;
    });
    c.bad = c.unconfirmed + c.refused;
    return c;
  };
  O.opText = function (op) {
    var c = O.opCounts(op), parts = [];
    if (c.confirmed) parts.push(c.confirmed + ' confirmed');
    if (c.sent) parts.push(c.sent + ' sent (no feedback)');
    if (c.working) parts.push(c.working + ' working');
    if (c.unconfirmed) parts.push(c.unconfirmed + ' not confirmed');
    if (c.refused) parts.push(c.refused + ' not done');
    if (c.replaced) parts.push(c.replaced + ' replaced');
    return parts.join(', ') || 'nothing to do';
  };
  O.opTone = function (op) { var c = O.opCounts(op); return !op.done ? 'teal' : (c.bad ? 'warn' : (c.confirmed ? 'ok' : 'info')); };
  O.opSheet = function (op) {
    VF.modal({ title: op.label || 'Operation', icon: 'list', body: h('div.col', h('p.muted', (op.done ? 'Finished' : 'Still working') + ': ' + O.opText(op) + '.'), VF.outcomeList(op.targets)), actions: [{ label: 'Close', kind: 'primary', value: null }] });
  };

  var opSeen = {};
  function paintActivity() {
    if (!ui) return;
    var doc = O.doc(), now = Date.now();
    var ops = VF.asList(doc.operations);
    var shown = [], sig = '', present = {};
    VF.asList(doc.running).forEach(function (x) { shown.push({ run: x }); sig += 'x' + x.id + x.status + '|'; });
    ops.forEach(function (op) {
      present[op.id] = true;
      var seen = opSeen[op.id];
      if (!seen) seen = opSeen[op.id] = { old: !!op.done && (Number(doc.time) || 0) - (Number(op.finishedAt) || 0) > 5, doneAt: 0, dismissed: false };
      if (op.done && !seen.doneAt) seen.doneAt = now;
      var bad = O.opCounts(op).bad > 0;
      /* A finished audio change that went well needs no line: the control itself shows it. */
      var quiet = !bad && !VF.asList(op.targets).some(function (t) { return t.kind === 'display'; });
      var keep = !op.done || (!seen.old && !seen.dismissed && !quiet && now - seen.doneAt < (bad ? 45000 : 6000));
      if (keep) { shown.push({ op: op }); sig += op.id + ':' + O.opText(op) + (op.done ? 'd' : '') + '|'; }
    });
    Object.keys(opSeen).forEach(function (id) { if (!present[id]) delete opSeen[id]; });
    var active = doc.activeScene && doc.activeScene.name ? doc.activeScene : null;
    sig = (active ? 'a' + active.id + active.at : '') + '|' + sig;
    O.patch(ui.activity, sig, function () {
      var lead = active ? h('div.op-act.idle', VF.icon('zap', 'sm'), h('span.op-act-text', 'Active scene: ', h('b', active.name), active.at ? ' since ' + VF.fmtTime(active.at) : ''))
        : (O.list('scenes').length && !shown.length ? h('div.op-act.idle.none', h('span.op-act-text', 'No scene active')) : null);
      return [lead].concat(shown.map(function (it) {
        if (it.run) {
          return h('div.op-act.teal', h('span.dot.teal.pulse'), h('span.op-act-text', h('b', it.run.name), it.run.status === 'settling' ? ': waiting for the devices to confirm' : ': running'));
        }
        var op = it.op, tone = O.opTone(op);
        return h('div.op-act.' + tone, h('span.dot.' + tone + (op.done ? '' : '.pulse')),
          h('span.op-act-text', h('b', op.label || 'Operation'), ': ' + O.opText(op)),
          h('button.btn.sm.ghost', { type: 'button', onclick: function () { O.opSheet(op); } }, 'Details'),
          op.done ? h('button.btn.sm.ghost.icon', { type: 'button', 'aria-label': 'Dismiss', onclick: function () { opSeen[op.id].dismissed = true; paintActivity(); } }, VF.icon('x', 'sm')) : null);
      }));
    });
  }

  function paint() {
    if (!ui) return;
    var doc = O.doc();
    O.setClass(ui.sim, 'hidden', doc.simulation !== true);
    var open = doc.venueStatus === 'open';
    O.setText(ui.venueText, doc.venueStatus ? (open ? 'Venue Open' : 'Venue Closed') : 'Venue');
    ui.venueDot.className = 'dot ' + (open ? 'ok' : '');
    O.setClass(ui.venue, 'ok', open);
    paintBanners();
    paintActivity();
    if (current && current.view && current.view.update) {
      try { current.view.update(); } catch (e) { console.error('VenueFlow view update', e); }
    }
    live.slice().forEach(function (fn) { try { fn(); } catch (e) { console.error(e); } });
  }
  var paintQueued = false;
  O.repaint = function () {
    if (paintQueued) return;
    paintQueued = true;
    setTimeout(function () { paintQueued = false; paint(); }, 0);
  };

  /* ── start ───────────────────────────────────────────────────────────── */
  function hello() {
    clearTimeout(retryTimer);
    return VF.api('HELLO', {}, { since: false }).then(function (r) {
      if (!r.ok || !r.data) { showUnreachable(r); return; }
      var d = r.data;
      O.hello = d;
      if (!d.published) {
        notice('settings', 'This venue has not been set up yet', 'Your installer needs to publish the venue before this screen can control anything.',
          d.studioEnabled ? h('a.btn', { href: studioUrl() }, VF.icon('settings'), 'Open Installer Studio') : null);
        clearTimeout(retryTimer);
        retryTimer = setTimeout(function () { if (!ui) hello(); }, 15000);
        return;
      }
      if (d.needsSignIn || !d.profile) { lastProfileId = null; showSignIn(null); return; }
      enter(d);
    });
  }
  /* The state document carries no configuration version, so look again now and then:
     a republished venue or a changed profile redraws the page. */
  function recheck() {
    if (!ui || document.hidden || document.querySelector('.vf-backdrop')) return;
    VF.api('HELLO', {}, { since: false }).then(function (r) {
      if (!ui || !r.ok || !r.data || document.querySelector('.vf-backdrop')) return;
      var d = r.data;
      if (!d.published) { hello(); return; }
      if (d.needsSignIn || !d.profile) { O.hello = d; lastProfileId = null; showSignIn(null); return; }
      if (dataKey(d) !== lastKey) { enter(d); VF.toast('The venue setup was updated.'); }
    });
  }

  O.start = function () {
    root = document.getElementById('root');
    O.asStudio = new URLSearchParams(location.search).get('as') === 'studio';
    VF.session.use(O.asStudio ? 'studio' : 'op');
    VF.on('state', O.repaint);
    /* The state names the published version: when it changes, load the new setup at once
       (the 60 s recheck below remains as the safety net). */
    var seenVersion = null;
    VF.on('state', function (doc) {
      var v = doc && doc.configVersion;
      if (!v) return;
      if (seenVersion !== null && v !== seenVersion) recheck();
      seenVersion = v;
    });
    VF.on('online', function (on) { isOnline = on !== false; paintOnline(); });
    VF.on('signedout', function () { lastProfileId = null; hello(); });
    setInterval(function () { paintClock(); paintActivity(); }, 1000);
    setInterval(recheck, 60000);
    window.addEventListener('resize', VF.debounce(fitHeader, 150));
    hello();
  };

  return O;
})();
</script>
<script>
/* Interface B, Command Center: select displays, choose a source, route.
   Two ways of working: display first (select, pick, route) and source first
   (pick a source, then every display tapped is routed at once). */
(function () {
  'use strict';
  var h = VF.h, O = Operator;
  /* Kept across view switches (memory only). */
  var S = { filter: 'all', mode: 'display', floorId: '' };

  O.register('command', function (host) {
    var displays = O.list('displays');
    var canRoute = O.can('routeVideo'), canPower = O.can('power');
    if (!canRoute) S.mode = 'display';
    if (!displays.length) {
      VF.mount(host, h('div.empty', 'No display is available to this profile.'));
      return {};
    }

    /* filters: All, each area, each group */
    var filters = [{ id: 'all', label: 'All', ids: displays.map(function (d) { return d.id; }) }];
    O.list('areas').forEach(function (a) {
      var ids = displays.filter(function (d) { return d.areaId === a.id; }).map(function (d) { return d.id; });
      if (ids.length) filters.push({ id: 'area:' + a.id, label: a.name, ids: ids });
    });
    O.list('groups').forEach(function (g) {
      var ids = VF.asList(g.displayIds).filter(function (id) { return O.find('displays', id); });
      if (ids.length) filters.push({ id: 'group:' + g.id, label: g.name, ids: ids, group: true });
    });
    function filter() {
      for (var i = 0; i < filters.length; i++) if (filters[i].id === S.filter) return filters[i];
      S.filter = 'all';
      return filters[0];
    }

    /* top row: scenes, the selection count, All Off */
    var scenes = O.sceneBar();
    var count = h('span.chip.teal.op-cc-count');
    var top = h('div.op-cc-top', scenes || h('div.grow'), count, O.allOffButton('.sm'));

    /* step heads */
    function step() {
      var no = h('span.op-stepno'), title = h('h3.grow.ellipsis');
      var el = h('div.op-step', no, title);
      el.set = function (n, text) { O.setText(no, n); O.setText(title, text); };
      return el;
    }
    var stepDisplays = step(), stepSources = step(), stepRoute = step();

    /* 1: displays */
    var modeSeg = canRoute ? h('div.seg.op-cc-mode', { role: 'group', 'aria-label': 'How to route' },
      h('button', { type: 'button', dataset: { mode: 'display' }, title: 'Select displays, choose a source, then route', onclick: function () { setMode('display'); } }, 'Select first'),
      h('button', { type: 'button', dataset: { mode: 'source' }, title: 'Choose a source, then tap each display to route it at once', onclick: function () { setMode('source'); } }, 'Source first')) : null;
    var chipRow = h('div.op-cc-filters.scroll');
    var chipEls = filters.map(function (f) {
      var b = h('button.op-fchip' + (f.group ? '.group' : ''), { type: 'button', onclick: function () { S.filter = f.id; buildGrid(); update(); } }, f.label, h('span.op-fchip-n', String(f.ids.length)));
      b._f = f;
      chipRow.appendChild(b);
      return b;
    });
    var selAll = h('button.btn.sm', { type: 'button', onclick: function () { O.selection.add(filter().ids); } }, 'Select All');
    var selNone = h('button.btn.sm.ghost', { type: 'button', onclick: function () { O.selection.remove(filter().ids); } }, 'Clear');
    var grid = h('div.op-cc-grid.scroll');
    var tiles = [];
    var busyTiles = {};

    function tapTile(d) {
      if (S.mode !== 'source') { O.selection.toggle(d.id); return; }
      if (!O.pick.sourceId) { VF.toast('Choose a source first.', 'warn'); return; }
      if (busyTiles[d.id]) return;
      busyTiles[d.id] = true;
      O.route(O.pick.sourceId, [d.id], listenZoneId()).then(function () { delete busyTiles[d.id]; });
    }
    function buildGrid() {
      var f = filter();
      tiles = [];
      VF.clear(grid);
      f.ids.forEach(function (id) {
        var d = O.find('displays', id);
        if (!d) return;
        var chip = O.displayChip();
        var src = h('div.op-tile-src.ellipsis');
        var mark = h('span.op-check', VF.icon('check', 'sm'));
        var note = h('span.op-tile-note', 'Cannot show');
        var el = h('button.op-tile', { type: 'button', role: 'checkbox', onclick: function () { tapTile(d); } },
          h('div.op-tile-top', mark, h('div.grow.ellipsis.op-tile-name', d.name), h('span.op-tile-area.ellipsis', O.areaName(d.areaId))),
          h('div.op-tile-now', chip, src, note));
        grid.appendChild(el);
        tiles.push({ el: el, d: d, chip: chip, src: src });
      });
      grid.scrollTop = 0;
    }

    /* 2: sources */
    var sources = O.sourceList({
      get: function () { return O.pick.sourceId; },
      set: function (id) { O.pick.sourceId = id; update(); },
      note: function (s) {
        if (S.mode === 'source') return '';
        var blocked = O.selection.ids().filter(function (id) { return !O.canShow(O.find('displays', id), s.id); }).length;
        return blocked ? blocked + ' selected cannot show this' : '';
      }
    });

    /* 3: route, listen, power */
    var zones = O.listenZones();
    var follow = zones.length ? h('select.field', { 'aria-label': 'Audio follow', onchange: function () { O.pick.zoneId = follow.value; O.pick.listen = follow.value !== ''; update(); } },
      h('option', { value: '' }, 'No audio change'), zones.map(function (z) { return h('option', { value: z.id }, 'Listen in ' + z.name); })) : null;
    var followHint = h('div.hint.op-cc-hint');
    function listenZoneId() {
      if (!O.pick.listen || !O.pick.zoneId) return '';
      var z = O.find('audioZones', O.pick.zoneId);
      return z && !O.listenProblem(z, O.pick.sourceId) ? z.id : '';
    }
    var routing = false;
    var routeText = h('span');
    var routeBtn = canRoute ? h('button.btn.primary.lg.block.op-cc-go', { type: 'button', onclick: function () {
      var ids = O.selection.ids();
      if (routing || !ids.length || !O.pick.sourceId) return;
      routing = true; update();
      O.route(O.pick.sourceId, ids, listenZoneId()).then(function () { routing = false; update(); });
    } }, VF.icon('route'), routeText) : null;
    var sourceHint = h('div.banner.info.op-cc-sfhint.hidden', VF.icon('info'), h('div', 'Each display you tap is routed at once.'));
    function powerBtn(power) {
      var b = h('button.btn' + (power === 'off' ? '' : '.outline'), { type: 'button', onclick: function () {
        var ids = O.selection.ids();
        if (!ids.length || b.disabled) return;
        b._busy = true; b.disabled = true;
        O.power(ids, power).then(function () { b._busy = false; update(); });
      } }, VF.icon('power'), power === 'on' ? 'Power On' : 'Power Off');
      return b;
    }
    var pOn = canPower ? powerBtn('on') : null, pOff = canPower ? powerBtn('off') : null;

    /* compact venue map (shown by CSS only when the screen is wide enough) */
    var floors = O.list('floors').filter(function (f) { return O.floorDisplays(f.id).some(O.placed); });
    var mapHost = h('div.op-cc-maphost');
    var mapSeg = null, plan = null;
    function buildMap() {
      var floor = O.find('floors', S.floorId) || floors[0];
      if (!floor) return;
      S.floorId = floor.id;
      plan = O.plan(floor, { compact: true, onDisplay: function (d) { tapTile(d); }, onArea: S.mode === 'source' ? null : function (a) {
        O.selection.toggleMany(displays.filter(function (d) { return d.areaId === a.id; }).map(function (d) { return d.id; }));
      } });
      VF.mount(mapHost, plan.el);
      if (mapSeg) Array.prototype.forEach.call(mapSeg.children, function (b) { O.setClass(b, 'on', b.dataset.floor === floor.id); });
    }
    if (floors.length > 1) {
      mapSeg = h('div.seg.op-cc-mapseg', floors.map(function (f) { return h('button', { type: 'button', dataset: { floor: f.id }, onclick: function () { S.floorId = f.id; buildMap(); } }, f.name); }));
    }
    var map = floors.length ? h('div.op-cc-map', mapSeg, mapHost) : null;

    /* audio zones along the bottom */
    var zoneCards = O.can('audio') ? O.list('audioZones').map(function (z) { return O.zoneControl(z, { variant: 'card', source: false, presets: false, off: false, more: true }); }) : [];
    var zoneRow = zoneCards.length ? h('div.op-cc-zones.scroll', zoneCards) : null;

    function setMode(mode) {
      S.mode = mode;
      buildMap();
      update();
    }

    VF.mount(host,
      top,
      h('div.op-cc-body',
        h('section.panel.op-cc-displays', h('div.op-cc-head', stepDisplays, modeSeg), h('div.op-cc-tools', chipRow, selAll, selNone), grid),
        h('section.panel.op-cc-sources', stepSources, h('div.op-cc-srcwrap.scroll', sources)),
        h('section.panel.op-cc-route', stepRoute,
          h('div.op-cc-routebody.scroll',
            follow ? h('label.lbl', 'Audio follow', follow, followHint) : null,
            sourceHint, routeBtn,
            (pOn || pOff) ? h('div.op-cc-power', pOn, pOff) : null,
            map))),
      zoneRow);
    buildGrid();
    buildMap();

    function update() {
      var sel = O.selection.ids(), n = sel.length;
      var sourceFirst = S.mode === 'source';
      var src = O.find('sources', O.pick.sourceId);
      var f = filter();

      O.setText(count, O.plural(n, 'display') + ' selected');
      O.setClass(count, 'hidden', sourceFirst);
      if (scenes) scenes.update();

      if (sourceFirst) {
        stepSources.set('1', 'Choose Source'); stepDisplays.set('2', 'Tap Displays to Route'); stepRoute.set('3', 'Listen');
      } else {
        stepDisplays.set('1', 'Select Displays'); stepSources.set('2', 'Choose Source'); stepRoute.set('3', 'Route & Listen');
      }
      O.setClass(host, 'source-first', sourceFirst);
      if (modeSeg) Array.prototype.forEach.call(modeSeg.children, function (b) { O.setClass(b, 'on', b.dataset.mode === S.mode); });
      chipEls.forEach(function (b) { O.setClass(b, 'on', b._f.id === f.id); });
      selAll.disabled = sourceFirst || f.ids.every(function (id) { return O.selection.has(id); });
      selNone.disabled = sourceFirst || !f.ids.some(function (id) { return O.selection.has(id); });

      tiles.forEach(function (t) {
        var info = O.displayInfo(t.d);
        var on = O.selection.has(t.d.id);
        var cls = 'op-tile ' + info.key + (on && !sourceFirst ? ' sel' : '') + (src && !O.canShow(t.d, src.id) ? ' blocked' : '');
        if (t.el.className !== cls) t.el.className = cls;
        O.setAttr(t.el, 'aria-checked', on && !sourceFirst ? 'true' : 'false');
        t.chip.set(info);
        O.setText(t.src, info.sourceName || (info.on ? 'No source' : ''));
      });
      sources.update();

      if (follow) {
        var zid = O.pick.listen ? O.pick.zoneId : '';
        if (document.activeElement !== follow && follow.value !== zid) follow.value = zid;
        var problem = zid ? O.listenProblem(O.find('audioZones', zid), O.pick.sourceId) : '';
        O.setText(followHint, problem ? problem + ' The sound will not change.' : (zid ? 'The sound in that zone follows the source you route.' : ''));
        O.setClass(followHint, 'st-failed', !!problem);
      }
      if (routeBtn) {
        O.setClass(routeBtn, 'hidden', sourceFirst);
        O.setText(routeText, routing ? 'Sending' : (!n ? 'Select displays' : (!src ? 'Choose a source' : 'Route to ' + O.plural(n, 'Display'))));
        routeBtn.disabled = routing || !n || !src;
      }
      O.setClass(sourceHint, 'hidden', !sourceFirst);
      if (pOn) { pOn.disabled = !n || pOn._busy === true; O.setClass(pOn.parentNode, 'hidden', sourceFirst); }
      if (pOff) pOff.disabled = !n || pOff._busy === true;
      if (plan) plan.update();
      zoneCards.forEach(function (z) { z.update(); });
    }
    return { update: update };
  });
})();
</script>
<script>
/* Interface A, Visual Floor Plan: the venue from above. Tap displays where they
   really are, then route, listen and power them from the side panel. */
(function () {
  'use strict';
  var h = VF.h, O = Operator;
  /* Kept across view switches (memory only). */
  var S = { floorId: '', zoneId: '' };

  O.register('floorplan', function (host) {
    var floors = O.list('floors');
    var canRoute = O.can('routeVideo'), canPower = O.can('power');
    if (!floors.length) {
      VF.mount(host, h('div.empty', 'No floor is available to this profile.'));
      return {};
    }
    var floor = null, plan = null;
    var planHost = h('div.op-fp-plan');
    var floorSeg = floors.length > 1 ? h('div.seg.op-fp-floors', { role: 'group', 'aria-label': 'Floor' }, floors.map(function (f) {
      return h('button', { type: 'button', dataset: { floor: f.id }, onclick: function () { setFloor(f.id); } }, f.name);
    })) : null;

    function idsOnFloor() { return O.floorDisplays(floor.id).map(function (d) { return d.id; }); }

    /* toolbar: groups, Select All, Clear */
    var groupRow = h('div.op-fp-groups.scroll');
    var groupEls = [];
    function buildGroups() {
      VF.clear(groupRow); groupEls = [];
      var onFloor = {};
      idsOnFloor().forEach(function (id) { onFloor[id] = true; });
      O.list('groups').forEach(function (g) {
        var ids = VF.asList(g.displayIds).filter(function (id) { return onFloor[id]; });
        if (!ids.length) return;
        var b = h('button.op-fchip.group', { type: 'button', title: 'Select ' + g.name, onclick: function () { O.selection.toggleMany(ids); } }, g.name, h('span.op-fchip-n', String(ids.length)));
        b._ids = ids;
        groupRow.appendChild(b); groupEls.push(b);
      });
    }
    var selAll = h('button.btn.sm', { type: 'button', onclick: function () { O.selection.add(idsOnFloor()); } }, VF.icon('check', 'sm'), 'Select All');
    var selNone = h('button.btn.sm.ghost', { type: 'button', onclick: function () { O.selection.clear(); } }, 'Clear');

    /* side panel */
    var selTitle = h('h3');
    var selList = h('div.list.op-fp-sel');
    var unplacedBox = h('div.op-fp-unplaced');
    var unplacedEls = [];
    function buildUnplaced() {
      unplacedEls = [];
      var list = O.unplacedDisplays(floor.id);
      VF.clear(unplacedBox);
      if (!list.length) return;
      unplacedBox.appendChild(h('h4', 'Not on the plan'));
      var wrap = h('div.op-fp-unplaced-list');
      list.forEach(function (d) {
        var st = h('span.small');
        var b = h('button.op-mini', { type: 'button', role: 'checkbox', onclick: function () { O.selection.toggle(d.id); } }, h('span.op-check', VF.icon('check', 'sm')), h('span.grow.ellipsis', d.name), st);
        wrap.appendChild(b);
        unplacedEls.push({ el: b, d: d, st: st });
      });
      unplacedBox.appendChild(wrap);
    }

    /* source picker: one button that opens the list */
    var srcText = h('span.grow.ellipsis');
    function pickSource() {
      var closer = null;
      var list = O.sourceList({
        get: function () { return O.pick.sourceId; },
        set: function (id) { O.pick.sourceId = id; update(); if (closer) closer(id); },
        note: function (s) {
          var blocked = O.selection.ids().filter(function (id) { return !O.canShow(O.find('displays', id), s.id); }).length;
          return blocked ? O.plural(blocked, 'selected display') + ' cannot show this' : '';
        }
      });
      list.update();
      VF.modal({ title: 'Choose a source', icon: 'monitor', body: list, actions: [{ label: 'Cancel', kind: 'ghost', value: null }], onOpen: function (close) { closer = close; } });
    }
    var srcBtn = h('button.btn.block.op-fp-srcbtn', { type: 'button', 'aria-haspopup': 'dialog', onclick: pickSource }, VF.icon('monitor'), srcText, VF.icon('chevron-down', 'sm'));
    var routing = false;
    var routeText = h('span', 'Route Video');
    var routeBtn = canRoute ? h('button.btn.primary.lg.block', { type: 'button', onclick: function () {
      var ids = O.selection.ids();
      if (routing || !ids.length || !O.pick.sourceId) return;
      routing = true; update();
      O.route(O.pick.sourceId, ids, listenZoneId()).then(function () { routing = false; update(); });
    } }, VF.icon('route'), routeText) : null;

    /* listen: send the sound of the routed source to one audio zone */
    var zones = O.listenZones();
    var listenToggle = h('button.toggle', { type: 'button', role: 'switch', 'aria-label': 'Listen', onclick: function () {
      O.pick.listen = !O.pick.listen;
      if (O.pick.listen && !O.pick.zoneId) O.pick.zoneId = defaultListenZone();
      update();
    } });
    var listenName = h('span.grow.ellipsis');
    var listenSelect = zones.length > 1 ? h('select.field.op-fp-listenzone', { 'aria-label': 'Listen in', onchange: function () { O.pick.zoneId = listenSelect.value; O.pick.listen = true; update(); } },
      zones.map(function (z) { return h('option', { value: z.id }, z.name); })) : null;
    var listenHint = h('div.hint');
    var listenRow = zones.length && canRoute ? h('div.op-fp-listen', h('div.row', listenToggle, listenName, listenSelect), listenHint) : null;
    function defaultListenZone() {
      var sel = O.selection.ids();
      for (var i = 0; i < sel.length; i++) {
        var d = O.find('displays', sel[i]);
        if (d && d.audioZoneId && zones.some(function (z) { return z.id === d.audioZoneId; })) return d.audioZoneId;
      }
      return zones.length ? zones[0].id : '';
    }
    function listenZone() { return O.find('audioZones', O.pick.zoneId) || O.find('audioZones', defaultListenZone()); }
    function listenZoneId() {
      if (!O.pick.listen || !listenRow) return '';
      var z = listenZone();
      return z && !O.listenProblem(z, O.pick.sourceId) ? z.id : '';
    }

    function powerBtn(power) {
      var b = h('button.btn.grow' + (power === 'off' ? '' : '.outline'), { type: 'button', onclick: function () {
        var ids = O.selection.ids();
        if (!ids.length || b.disabled) return;
        b._busy = true; b.disabled = true;
        O.power(ids, power).then(function () { b._busy = false; update(); });
      } }, VF.icon('power'), power === 'on' ? 'Power On' : 'Power Off');
      return b;
    }
    var pOn = canPower ? powerBtn('on') : null, pOff = canPower ? powerBtn('off') : null;

    var side = h('aside.panel.op-fp-side.scroll',
      h('div.op-fp-block', selTitle, selList),
      unplacedBox,
      canRoute ? srcBtn : null,
      routeBtn, listenRow,
      (pOn || pOff) ? h('div.row.op-fp-power', pOn, pOff) : null);

    /* bottom bar: scene shortcuts and one audio zone */
    var scenes = O.sceneBar();
    var zoneList = O.can('audio') ? O.list('audioZones') : [];
    var zoneHost = h('div.op-fp-zone');
    var zoneCtl = null;
    var zoneSelect = zoneList.length > 1 ? h('select.field.op-fp-zonepick', { 'aria-label': 'Audio zone', onchange: function () { S.zoneId = zoneSelect.value; buildZone(); } },
      zoneList.map(function (z) { return h('option', { value: z.id }, z.name); })) : null;
    function buildZone() {
      var z = O.find('audioZones', S.zoneId);
      if (!z || zoneList.indexOf(z) < 0) z = zoneList[0];
      zoneCtl = null;
      if (!z) return;
      S.zoneId = z.id;
      if (zoneSelect) zoneSelect.value = z.id;
      zoneCtl = O.zoneControl(z, { variant: 'bar', source: false, presets: false, off: false });
      VF.mount(zoneHost, zoneCtl);
    }
    var bottom = (scenes || zoneList.length || O.can('allOff')) ? h('div.panel.op-fp-bottom',
      scenes || h('div.grow'),
      zoneList.length ? h('div.op-fp-audio', zoneSelect, zoneHost) : null,
      O.allOffButton('.sm')) : null;

    function setFloor(id) {
      floor = O.find('floors', id) || floors[0];
      S.floorId = floor.id;
      plan = O.plan(floor, {
        onDisplay: function (d) { O.selection.toggle(d.id); },
        onArea: function (a) { O.selection.toggleMany(O.floorDisplays(floor.id).filter(function (d) { return d.areaId === a.id; }).map(function (d) { return d.id; })); }
      });
      VF.mount(planHost, plan.el, plan.count ? null : h('div.op-fp-noplan.muted', 'No display has been placed on this floor yet.'));
      if (floorSeg) Array.prototype.forEach.call(floorSeg.children, function (b) { O.setClass(b, 'on', b.dataset.floor === floor.id); });
      buildGroups();
      buildUnplaced();
      update();
    }

    VF.mount(host,
      h('div.op-fp-bar', floorSeg, groupRow, selAll, selNone),
      h('div.op-fp-body', h('div.panel.op-fp-planwrap.scroll', planHost), side),
      bottom);
    buildZone();

    function update() {
      if (!plan) return;
      var sel = O.selection.ids(), n = sel.length;
      var src = O.find('sources', O.pick.sourceId);
      plan.update();
      groupEls.forEach(function (b) { O.setClass(b, 'on', b._ids.every(function (id) { return O.selection.has(id); })); });
      var onFloor = idsOnFloor();
      selAll.disabled = !onFloor.length || onFloor.every(function (id) { return O.selection.has(id); });
      selNone.disabled = !n;

      O.setText(selTitle, 'Selected Displays (' + n + ')');
      var sig = sel.map(function (id) { var i = O.displayInfo(O.find('displays', id)); return id + ':' + i.key + ':' + i.line; }).join('|');
      O.patch(selList, 'n' + n + '|' + sig, function () {
        if (!n) return h('div.empty.small', 'Tap displays on the plan, an area name, or a group.');
        return sel.map(function (id) {
          var d = O.find('displays', id), info = O.displayInfo(d);
          var chip = O.displayChip(); chip.set(info);
          return h('div.item.op-fp-selrow', h('div.grow', h('div.ellipsis', d.name), h('div.small.muted.ellipsis', info.sourceName || O.areaName(d.areaId))), chip,
            h('button.btn.ghost.icon.sm', { type: 'button', 'aria-label': 'Remove ' + d.name, onclick: function () { O.selection.toggle(id); } }, VF.icon('x', 'sm')));
        });
      });
      unplacedEls.forEach(function (u) {
        var info = O.displayInfo(u.d);
        var cls = 'op-mini ' + info.key + (O.selection.has(u.d.id) ? ' sel' : '');
        if (u.el.className !== cls) u.el.className = cls;
        O.setAttr(u.el, 'aria-checked', O.selection.has(u.d.id) ? 'true' : 'false');
        O.setText(u.st, info.line);
      });

      O.setText(srcText, 'Source: ' + (src ? src.name : 'choose one'));
      O.setClass(srcBtn, 'on', !!src);
      if (routeBtn) {
        O.setText(routeText, routing ? 'Sending' : (n ? 'Route Video to ' + O.plural(n, 'Display') : 'Route Video'));
        routeBtn.disabled = routing || !n || !src;
      }
      if (listenRow) {
        var z = listenZone();
        var on = O.pick.listen && !!z;
        O.setClass(listenToggle, 'on', on);
        O.setAttr(listenToggle, 'aria-checked', on ? 'true' : 'false');
        O.setText(listenName, listenSelect ? 'Listen in' : 'Listen in ' + (z ? z.name : ''));
        if (listenSelect && z && document.activeElement !== listenSelect && listenSelect.value !== z.id) listenSelect.value = z.id;
        var problem = on ? O.listenProblem(z, O.pick.sourceId) : '';
        O.setText(listenHint, problem ? problem + ' The sound will not change.' : (on ? 'The sound in ' + z.name + ' follows the routed source.' : ''));
        O.setClass(listenHint, 'st-failed', !!problem);
      }
      if (pOn) pOn.disabled = !n || pOn._busy === true;
      if (pOff) pOff.disabled = !n || pOff._busy === true;
      if (scenes) scenes.update();
      if (zoneCtl) zoneCtl.update();
    }

    setFloor(S.floorId);
    return { update: update };
  });
})();
</script>
<script>
/* Interface C, Simplified Room Control: one room, a few very large buttons.
   Driven by the room panels of the published configuration (config.rooms). */
(function () {
  'use strict';
  var h = VF.h, O = Operator;
  var S = { roomId: '' };

  function cell(kind, id, field) { return VF.state.cell(kind, id, field); }
  function word(c) { return c.status === 'pending' ? 'working' : (c.status === 'failed' || (c.status === 'unknown' && c.errorCode) ? 'not confirmed' : ''); }

  O.register('room', function (host) {
    var rooms = O.list('rooms');
    if (!rooms.length) {
      VF.mount(host, h('div.op-room-none', VF.icon('home', 'xl'), h('h2', 'No room panel here'), h('p.muted', 'No room panel is available to this profile. Ask your installer to add one for this room.')));
      return {};
    }
    var body = h('div.op-room-body');
    var picker = rooms.length > 1 ? h('div.seg.op-room-pick', { role: 'group', 'aria-label': 'Room' }, rooms.map(function (r) {
      return h('button', { type: 'button', dataset: { room: r.id }, onclick: function () { build(r.id); } }, r.name);
    })) : null;
    var parts = [];       // update functions of the room now shown

    function build(id) {
      var room = O.find('rooms', id) || rooms[0];
      S.roomId = room.id;
      parts = [];
      if (picker) Array.prototype.forEach.call(picker.children, function (b) { O.setClass(b, 'on', b.dataset.room === room.id); });

      var displays = VF.asList(room.displayIds).map(function (x) { return O.find('displays', x); }).filter(Boolean);
      var zone = room.volumeZoneId && O.can('audio') ? O.find('audioZones', room.volumeZoneId) : null;
      var lighting = room.lightingId ? O.find('lighting', room.lightingId) : null;
      var shades = VF.asList(room.shadeIds).map(function (x) { return O.find('shades', x); }).filter(Boolean);

      var roomScenes = VF.asList(room.buttons).map(function (b) { return O.find('scenes', b.sceneId); }).filter(Boolean);

      /* head: the room name and whether anything in it needs a look */
      var ready = h('span.chip'), readyDot = h('span.dot'), readyText = h('span');
      VF.append(ready, [readyDot, readyText]);
      parts.push(function () {
        var working = false, trouble = false;
        displays.forEach(function (d) { var k = O.displayInfo(d).key; if (k === 'working') working = true; if (k === 'failed' || k === 'offline') trouble = true; });
        if (zone) ['power', 'source', 'volume', 'mute'].forEach(function (f) { var w = word(cell('zones', zone.id, f)); if (w === 'working') working = true; if (w === 'not confirmed') trouble = true; });
        var running = roomScenes.some(function (s) { return O.sceneState(s).running; });
        var cls = 'chip op-room-ready ' + (trouble ? 'warn' : (working || running ? 'teal' : 'ok'));
        if (ready.className !== cls) ready.className = cls;
        O.setClass(readyDot, 'pulse', !trouble && (working || running));
        O.setText(readyText, trouble ? 'Needs attention' : (working || running ? 'Working' : 'Room Ready'));
      });

      /* the big buttons */
      var buttons = VF.asList(room.buttons).map(function (b) {
        var scene = O.find('scenes', b.sceneId);
        if (!scene) return null;
        var tag = h('span.op-big-tag');
        var el = h('button.op-big' + (b.icon === 'power' ? '.off' : ''), { type: 'button', onclick: function () {
          if (el.disabled) return;
          el.disabled = true;
          O.activateScene(scene, { areaId: room.areaId }).then(function () { el.disabled = false; });
        } }, VF.sceneIcon(b.icon || scene.icon, 'xl'), h('span.op-big-label', b.label || scene.name), tag);
        parts.push(function () {
          var st = O.sceneState(scene);
          O.setClass(el, 'on', st.active);
          O.setClass(el, 'busy', st.running);
          O.setAttr(el, 'aria-pressed', st.active ? 'true' : 'false');
          O.setText(tag, st.running ? 'Starting' : (st.active ? 'Current mode' : ''));
        });
        return el;
      }).filter(Boolean);

      /* current mode strip */
      var mode = [];
      function modeCell(icon, label) {
        var value = h('div.op-mode-value'), sub = h('div.small.muted.ellipsis');
        mode.push(h('div.op-mode-cell', VF.icon(icon, 'lg'), h('div.grow', h('div.tiny.muted.op-mode-label', label), value, sub)));
        return { value: value, sub: sub };
      }
      if (displays.length) {
        var mDisp = modeCell('tv', 'Displays');
        parts.push(function () {
          var on = 0, names = {}, flags = [];
          displays.forEach(function (d) {
            var i = O.displayInfo(d);
            if (i.on) { on++; if (i.sourceName) names[i.sourceName] = true; }
            if (i.key === 'working' || i.key === 'failed' || i.key === 'offline') flags.push(i.label.toLowerCase());
          });
          O.setText(mDisp.value, on + ' of ' + displays.length + ' on');
          O.setText(mDisp.sub, flags.length ? flags[0] : Object.keys(names).join(', '));
        });
      }
      if (zone) {
        var mAudio = modeCell('volume', 'Audio');
        parts.push(function () {
          var p = cell('zones', zone.id, 'power'), v = cell('zones', zone.id, 'volume'), m = cell('zones', zone.id, 'mute'), s = cell('zones', zone.id, 'source');
          O.setText(mAudio.value, m.value === true ? 'Muted' : (p.value === 'off' ? 'Off' : (typeof v.value === 'number' ? v.value + '%' : 'Unknown')));
          O.setText(mAudio.sub, word(v) || word(m) || word(p) || (p.value === 'on' && s.value ? O.sourceName(s.value) : ''));
        });
      }
      if (lighting) {
        var mLight = modeCell('bulb', 'Lights');
        parts.push(function () {
          var c = cell('lighting', lighting.id, 'preset');
          var p = VF.byId(lighting.presets, c.value);
          O.setText(mLight.value, p ? p.name : 'Not set yet');
          O.setText(mLight.sub, p && c.status === 'commanded' ? 'sent, no feedback' : word(c));
        });
      }
      if (shades.length) {
        var mShade = modeCell('blinds', 'Shades');
        parts.push(function () {
          var vals = {}, sent = false, w = '';
          shades.forEach(function (s) { var c = cell('shades', s.id, 'position'); vals[c.value || ''] = true; if (c.status === 'commanded') sent = true; w = w || word(c); });
          var keys = Object.keys(vals);
          O.setText(mShade.value, keys.length > 1 ? 'Mixed' : (keys[0] === 'open' ? 'Open' : (keys[0] === 'closed' ? 'Closed' : 'Not set yet')));
          O.setText(mShade.sub, w || (sent ? 'sent, no feedback' : ''));
        });
      }

      /* optional blocks */
      var blocks = [];
      if (zone) {
        var ctl = O.zoneControl(zone, { variant: 'card', source: false, off: false });
        parts.push(function () { ctl.update(); });
        blocks.push(h('section.panel.pad.op-room-block', h('h4', 'Audio'), ctl));
      }
      if (lighting && VF.asList(lighting.presets).length) {
        var lightBtns = VF.asList(lighting.presets).map(function (p) {
          var b = h('button.btn.op-room-opt', { type: 'button', onclick: function () { O.send('LIGHTING_PRESET', { lightingId: lighting.id, presetId: p.id }); } }, VF.icon('bulb'), p.name);
          b._id = p.id;
          return b;
        });
        parts.push(function () {
          var c = cell('lighting', lighting.id, 'preset');
          lightBtns.forEach(function (b) { O.setClass(b, 'on', c.value === b._id && c.status !== 'failed'); });
        });
        blocks.push(h('section.panel.pad.op-room-block', h('h4', 'Lights'), h('div.op-room-opts', lightBtns)));
      }
      if (shades.length) {
        var rows = shades.map(function (s) {
          var open = h('button.btn.op-room-opt', { type: 'button', onclick: function () { O.send('SHADE', { shadeId: s.id, action: 'open' }); } }, VF.icon('arrow-up'), 'Open');
          var close = h('button.btn.op-room-opt', { type: 'button', onclick: function () { O.send('SHADE', { shadeId: s.id, action: 'close' }); } }, VF.icon('arrow-down'), 'Close');
          parts.push(function () {
            var c = cell('shades', s.id, 'position');
            O.setClass(open, 'on', c.value === 'open' && c.status !== 'failed');
            O.setClass(close, 'on', c.value === 'closed' && c.status !== 'failed');
          });
          return h('div.col.tight', shades.length > 1 ? h('div.small.muted', s.name) : null, h('div.op-room-opts', open, close));
        });
        blocks.push(h('section.panel.pad.op-room-block', h('h4', 'Shades'), rows));
      }
      if (room.showSources && displays.length && O.can('routeVideo')) {
        var routable = displays.filter(function (d) { return d.canRoute !== false; });
        var srcBtns = O.videoSources().filter(function (s) { return routable.some(function (d) { return O.canShow(d, s.id); }); }).map(function (s) {
          var b = h('button.btn.op-room-opt', { type: 'button', onclick: function () {
            if (b.disabled) return;
            b.disabled = true;
            O.route(s.id, routable.map(function (d) { return d.id; })).then(function () { b.disabled = false; });
          } }, O.sourceIcon(s), h('span.ellipsis', s.name));
          b._id = s.id;
          return b;
        });
        if (srcBtns.length) {
          parts.push(function () {
            srcBtns.forEach(function (b) {
              var showing = routable.filter(function (d) { var i = O.displayInfo(d); return i.on && i.source.value === b._id; }).length;
              O.setClass(b, 'on', showing > 0 && showing === routable.length);
            });
          });
          blocks.push(h('section.panel.pad.op-room-block.wide', h('h4', 'Source on ' + (routable.length === 1 ? routable[0].name : 'the room displays')), h('div.op-room-opts', srcBtns)));
        }
      }

      VF.mount(body,
        h('div.op-room-head', h('h1.ellipsis', room.name), ready),
        buttons.length ? h('div.op-room-buttons', { dataset: { n: String(Math.min(buttons.length, 4)) } }, buttons) : h('div.empty', 'This room panel has no button for this profile.'),
        mode.length ? h('div.panel.op-room-mode', h('h4', 'Current Mode'), h('div.op-mode-cells', mode)) : null,
        blocks.length ? h('div.op-room-blocks', blocks) : null);
      update();
    }
    function update() { parts.forEach(function (fn) { fn(); }); }

    VF.mount(host, h('div.op-room.scroll', picker, body));
    build(S.roomId);
    return { update: update };
  });
})();
</script>
<script>
/* Interface D, Manager Overview: how the venue is doing, what needs a look,
   scenes, open / close, All Off, and what was done recently. Calm and plain:
   a manager is not a technician. Every number comes from the driver's counts. */
(function () {
  'use strict';
  var h = VF.h, O = Operator;
  var S = { floorId: '', open: {} };

  function resolveAlert(alert) {
    var a = VF.asMap(alert.action);
    if (a.type === 'query') {
      var payload = {};
      if (VF.asList(a.displayIds).length) payload.displayIds = VF.asList(a.displayIds);
      return VF.api('QUERY_STATUS', payload).then(function (r) {
        var results = VF.asList(r.results);
        var failed = results.filter(function (x) { return x.status === 'failed'; });
        if (!r.ok) VF.toastReply(r);
        else if (failed.length) VF.modal({ title: 'Checked again', icon: 'alert', body: VF.outcomeList(results), actions: [{ label: 'Close', kind: 'primary', value: null }] });
        else VF.toast('Checked again. The screen now shows what Control4 reports.', 'ok');
      });
    }
    if (a.type === 'unmute') return O.send('AUDIO_MUTE', { zoneId: a.zoneId, muted: false });
    return Promise.resolve();
  }
  function displaySheet(d) {
    var info = O.displayInfo(d);
    var chip = O.displayChip(); chip.set(info);
    var actions = [{ label: 'Close', kind: d.hasFeedback ? 'ghost' : 'primary', value: null }];
    if (d.hasFeedback) actions.push({ label: 'Check again', kind: 'primary', icon: 'refresh', value: 'check' });
    VF.modal({ title: d.name, icon: 'tv', body: h('div.list',
      h('div.item', h('div.grow', 'Status'), chip),
      h('div.item', h('div.grow', 'Showing'), h('span.muted', info.sourceName || 'Nothing')),
      h('div.item', h('div.grow', 'Area'), h('span.muted', O.areaName(d.areaId) || 'None'))), actions: actions }).then(function (v) {
      if (v === 'check') resolveAlert({ action: { type: 'query', displayIds: [d.id] } });
    });
  }

  O.register('manager', function (host) {
    var displays = O.list('displays');

    /* stat tiles */
    function tile(label, icon) {
      var value = h('div.op-stat-value'), sub = h('div.small.muted.ellipsis');
      var el = h('div.op-stat', VF.icon(icon, 'lg'), h('div.grow', value, h('div.op-stat-label.ellipsis', label), sub));
      el.set = function (v, s, tone) { O.setText(value, v); O.setText(sub, s || ''); var cls = 'op-stat' + (tone ? ' ' + tone : ''); if (el.className !== cls) el.className = cls; };
      return el;
    }
    var tDisplays = tile('Displays', 'tv'), tOn = tile('On', 'check-circle'), tAttention = tile('Attention', 'alert'),
      tZones = tile('Audio Zones', 'volume'), tScene = tile('Active Scene', 'zap');
    var stats = h('div.op-mgr-stats', tDisplays, tOn, tAttention, tZones, tScene);

    /* venue layout */
    var floors = O.list('floors').filter(function (f) { return O.floorDisplays(f.id).some(O.placed); });
    var mapHost = h('div.op-mgr-maphost'), plan = null;
    var mapSeg = floors.length > 1 ? h('div.seg', floors.map(function (f) { return h('button', { type: 'button', dataset: { floor: f.id }, onclick: function () { buildMap(f.id); } }, f.name); })) : null;
    function buildMap(id) {
      var floor = O.find('floors', id) || floors[0];
      if (!floor) return;
      S.floorId = floor.id;
      plan = O.plan(floor, { compact: true, selection: false, onDisplay: displaySheet });
      VF.mount(mapHost, plan.el);
      if (mapSeg) Array.prototype.forEach.call(mapSeg.children, function (b) { O.setClass(b, 'on', b.dataset.floor === floor.id); });
    }
    var legend = h('div.op-mgr-legend', ['on', 'off', 'failed', 'offline'].map(function (k) {
      return h('span.op-legend', h('i.' + k), k === 'on' ? 'On' : (k === 'off' ? 'Off' : (k === 'failed' ? 'Not confirmed' : 'Offline or unknown')));
    }));
    var areaList = h('div.list.op-mgr-areas');

    /* scenes */
    var sceneCards = O.list('scenes').map(function (s) {
      var chip = h('span.chip.ok.hidden', h('span.dot'), 'Active');
      var btn = h('button.btn.sm.outline', { type: 'button', onclick: function () {
        if (btn.disabled) return;
        btn.disabled = true;
        O.activateScene(s).then(function () { btn.disabled = false; });
      } }, 'Activate');
      var el = h('div.card.op-mgr-scene', h('div.row', VF.sceneIcon(s.icon, 'lg'), h('h3.grow.ellipsis', s.name), chip),
        h('p.small.muted.op-mgr-scene-desc', s.description || (s.confirm ? 'Asks for confirmation before it runs.' : '')), h('div.row.end', btn));
      el.update = function () {
        var st = O.sceneState(s);
        O.setClass(el, 'on', st.active);
        O.setClass(chip, 'hidden', !st.active);
        O.setText(btn, st.running ? 'Running' : (st.active ? 'Run again' : 'Activate'));
      };
      return el;
    });

    /* attention, venue, activity */
    var alertList = h('div.list');
    var alertCount = h('span.chip');
    var venueText = h('div.grow');
    var venueBtn = O.can('venueStatus') ? h('button.btn', { type: 'button', onclick: function () { O.setVenueStatus(O.doc().venueStatus === 'open' ? 'closed' : 'open'); } }) : null;
    var runList = h('div.list');
    var runPanel = h('section.panel.hidden', h('div.panel-head', VF.icon('play'), h('h3', 'Running now')), h('div.panel-body', runList));
    var opList = h('div.list');

    VF.mount(host, h('div.op-mgr.scroll',
      stats,
      h('div.op-mgr-cols',
        h('div.op-mgr-main',
          displays.length ? h('section.panel', h('div.panel-head', VF.icon('map'), h('h3.grow', 'Venue'), mapSeg),
            h('div.panel-body.op-mgr-venue', floors.length ? h('div.op-mgr-map', mapHost, legend) : null, areaList)) : null,
          sceneCards.length ? h('section.panel', h('div.panel-head', VF.icon('zap'), h('h3', 'Scenes')), h('div.panel-body.op-mgr-scenes', sceneCards)) : null),
        h('div.op-mgr-side',
          O.can('viewAlerts') ? h('section.panel', h('div.panel-head', VF.icon('alert'), h('h3.grow', 'Needs attention'), alertCount), h('div.panel-body', alertList)) : null,
          h('section.panel', h('div.panel-head', VF.icon('building'), h('h3', 'Venue status')),
            h('div.panel-body.col', h('div.row', venueText, venueBtn),
              O.can('allOff') ? h('div.row.op-mgr-alloff', h('div.grow.small.muted', 'Switches off every display and audio zone. You see a preview first.'), O.allOffButton('')) : null)),
          runPanel,
          h('section.panel', h('div.panel-head', VF.icon('history'), h('h3', 'Recent activity')), h('div.panel-body', opList))))));
    buildMap(S.floorId);

    function update() {
      var doc = O.doc();
      var c = VF.asMap(VF.asMap(doc.counts).displays), z = VF.asMap(VF.asMap(doc.counts).zones);
      /* The driver's own counts: on and off as it knows them, and what it cannot vouch for. */
      var rest = [(c.off || 0) + ' off'];
      if (c.unknown) rest.push(c.unknown + ' unknown');
      if (c.offline) rest.push(c.offline + ' offline');
      tDisplays.set(String(c.total || 0), '');
      tOn.set(String(c.on || 0), rest.join(', '), c.on ? 'ok' : '');
      tAttention.set(String(c.attention || 0), c.attention ? 'see the list below' : 'all clear', c.attention ? 'warn' : '');
      tZones.set((z.on || 0) + ' of ' + (z.total || 0) + ' on', z.muted ? z.muted + ' muted' : '');
      tScene.set(doc.activeScene ? doc.activeScene.name : 'None', doc.activeScene && doc.activeScene.at ? 'since ' + VF.fmtTime(doc.activeScene.at) : '', doc.activeScene ? 'teal' : '');
      if (plan) plan.update();

      /* area summaries */
      var rows = O.list('areas').map(function (a) {
        var list = displays.filter(function (d) { return d.areaId === a.id; });
        var on = 0, bad = 0, working = 0;
        list.forEach(function (d) { var i = O.displayInfo(d); if (i.on) on++; if (i.key === 'failed' || i.key === 'offline') bad++; if (i.key === 'working') working++; });
        var audio = O.list('audioZones').filter(function (x) { return x.areaId === a.id; }).map(function (x) {
          var st = VF.asMap(VF.asMap(doc.zones)[x.id]);
          var v = st.volume || {}, m = st.mute || {}, p = st.power || {};
          return m.value === true ? 'Muted' : (p.value === 'off' ? 'Audio off' : (typeof v.value === 'number' ? 'Audio ' + v.value + '%' : 'Audio unknown'));
        });
        return { a: a, total: list.length, on: on, bad: bad, working: working, audio: audio };
      }).filter(function (r) { return r.total || r.audio.length; });
      O.patch(areaList, JSON.stringify(rows.map(function (r) { return [r.a.id, r.total, r.on, r.bad, r.working, r.audio]; })), function () {
        if (!rows.length) return h('div.empty.small', 'No area is set up.');
        return rows.map(function (r) {
          return h('div.item.op-mgr-area', h('div.grow', h('div.ellipsis', r.a.name), h('div.small.muted', r.total ? r.on + ' of ' + O.plural(r.total, 'display') + ' on' : 'No display')),
            r.working ? h('span.chip.teal', h('span.dot.pulse'), r.working + ' working') : null,
            r.bad ? h('span.chip.warn', h('span.dot'), r.bad + ' to check') : null,
            r.audio.map(function (t) { return h('span.chip' + (t === 'Muted' ? '.warn' : ''), VF.icon(t === 'Muted' ? 'volume-x' : 'volume', 'sm'), t); }));
        });
      });

      sceneCards.forEach(function (s) { s.update(); });

      /* alerts */
      if (O.can('viewAlerts')) {
        var alerts = VF.asList(doc.alerts);
        O.setText(alertCount, alerts.length ? String(alerts.length) : 'All clear');
        var acls = 'chip ' + (alerts.length ? 'warn' : 'ok');
        if (alertCount.className !== acls) alertCount.className = acls;
        O.patch(alertList, JSON.stringify(alerts.map(function (a) { return [a.id, a.title, a.detail, a.level]; })), function () {
          if (!alerts.length) return h('div.op-mgr-clear', VF.icon('check-circle', 'lg'), h('span', 'Nothing needs attention.'));
          return alerts.map(function (a) {
            var act = VF.asMap(a.action);
            var warn = a.level !== 'info';
            var label = act.type === 'query' ? 'Resolve' : (act.type === 'unmute' ? 'Unmute' : '');
            var btn = label ? h('button.btn.sm' + (warn ? '.warn' : ''), { type: 'button', onclick: function () {
              if (btn.disabled) return;
              btn.disabled = true;
              resolveAlert(a).then(function () { btn.disabled = false; });
            } }, label) : null;
            var dismiss = a.dismissable ? h('button.btn.sm.ghost', { type: 'button', onclick: function () { O.send('ALERT_DISMISS', { alertId: a.id }); } }, 'Dismiss') : null;
            return h('div.op-alert' + (warn ? '.warn' : '.info'), VF.icon(warn ? 'alert' : 'info'),
              h('div.grow', h('div.op-alert-title', a.title), a.detail ? h('div.small.op-alert-detail', a.detail) : null, a.at ? h('div.tiny.muted', VF.fmtTime(a.at)) : null),
              h('div.op-alert-actions', btn, dismiss));
          });
        });
      }

      /* venue */
      var open = doc.venueStatus === 'open';
      O.patch(venueText, 'v' + doc.venueStatus, function () {
        return [h('div', 'The venue is ', h('b', open ? 'open' : 'closed'), '.'), h('div.small.muted', open ? 'Close it at the end of the day.' : 'Open it when the day starts.')];
      });
      if (venueBtn) O.patch(venueBtn, 'b' + doc.venueStatus, function () { return [VF.icon(open ? 'moon' : 'sun'), open ? 'Close venue' : 'Open venue']; });

      /* running + recent */
      var running = VF.asList(doc.running);
      O.setClass(runPanel, 'hidden', !running.length);
      O.patch(runList, JSON.stringify(running), function () {
        return running.map(function (x) {
          return h('div.item', h('span.dot.teal.pulse'), h('div.grow', h('div.ellipsis', x.name), h('div.small.muted', (x.kind === 'rule' ? 'Automatic rule' : 'Scene') + ', started ' + VF.fmtTime(x.startedAt))), VF.outcomeChip(x.status === 'settling' ? 'waiting' : 'running'));
        });
      });
      var ops = VF.asList(doc.operations);
      O.patch(opList, JSON.stringify(ops.map(function (op) { return [op.id, O.opText(op), op.done, !!S.open[op.id]]; })), function () {
        if (!ops.length) return h('div.empty.small', 'Nothing has been done yet.');
        return ops.map(function (op) {
          var tone = O.opTone(op), isOpen = !!S.open[op.id];
          var head = h('button.op-oprow', { type: 'button', 'aria-expanded': isOpen ? 'true' : 'false', onclick: function () { S.open[op.id] = !S.open[op.id]; update(); } },
            h('span.dot.' + tone + (op.done ? '' : '.pulse')),
            h('div.grow', h('div.ellipsis', op.label || 'Operation'), h('div.small.muted', VF.fmtTime(op.startedAt) + ' · ' + O.opText(op))),
            VF.icon(isOpen ? 'chevron-up' : 'chevron-down', 'sm'));
          return h('div.op-op' + (isOpen ? '.open' : ''), head, isOpen ? VF.outcomeList(op.targets) : null);
        });
      });
    }
    return { update: update };
  });
})();
</script>
<script>
Operator.start();
</script>
</body>
</html>
]==]
